var SLOPE = {'3,2':1, '3,3':1, '3,4':1, '3,5':1, '2,3':1, '2,4':1};
var GOAL = 3 * COLS + 7, START = 3 * COLS + 0;
var ACTS = [
  {n:'U', dr:-1, dc:0, g:'↑'}, {n:'D', dr:1, dc:0, g:'↓'},
  {n:'L', dr:0, dc:-1, g:'←'}, {n:'R', dr:0, dc:1, g:'→'}, {n:'S', dr:0, dc:0, g:'●'}
];
var N = CLIFF * COLS;
var s, k, j, t, it;

function rc(i) { return [Math.floor(i / COLS), i % COLS]; }
function isSlope(i) { var p = rc(i); return SLOPE[p[0] + ',' + p[1]] === 1; }

// --- transition structure (deterministic part) ---
var AV = [], SUCC = [], SUCCRC = [];
for (s = 0; s < N; s++) {
  var p0 = rc(s);
  AV[s] = isSlope(s) ? [1, 2, 3, 4] : [0, 1, 2, 3, 4];
  SUCC[s] = []; SUCCRC[s] = [];
  for (k = 0; k < 5; k++) {
    var r2 = Math.max(0, Math.min(ROWS - 1, p0[0] + ACTS[k].dr));
    var c2 = Math.max(0, Math.min(COLS - 1, p0[1] + ACTS[k].dc));
    if (isSlope(s)) r2 = Math.min(ROWS - 1, r2 + 1);
    SUCCRC[s][k] = [r2, c2];
    SUCC[s][k] = (r2 === CLIFF) ? -1 : r2 * COLS + c2;
  }
}

// --- viability iteration (Algorithm 1) ---
var viable = [];
for (s = 0; s < N; s++) viable[s] = true;
var changed = true;
while (changed) {
  changed = false;
  for (s = 0; s < N; s++) {
    if (!viable[s]) continue;
    var ok = false;
    for (k = 0; k < AV[s].length; k++) { t = SUCC[s][AV[s][k]]; if (t >= 0 && viable[t]) { ok = true; break; } }
    if (!ok) { viable[s] = false; changed = true; }
  }

for (s = 0; s < N; s++) if (!viable[s] && TF[s] > Tf) Tf = TF[s];

// --- rewards and constants ---
function rew(i, P) { return (i === GOAL) ? P.Rg : -P.c; }
function constants(P) {
  var s, k, t;
  var RXU = 0, RQU = 0, RQV = Infinity; // cliff cells (failure states, reward 0) belong to X_U, their pairs to Q_U
  for (s = 0; s < N; s++) {
    var r0 = rew(s, P);
    if (!viable[s]) { if (r0 > RXU) RXU = r0; if (r0 > RQU) RQU = r0; continue; }
    for (k = 0; k < AV[s].length; k++) {
      t = SUCC[s][AV[s][k]];
      if (t >= 0 && viable[t]) { if (r0 < RQV) RQV = r0; } else { if (r0 > RQU) RQU = r0; }
    }
  }
  return {RXU: RXU, RQU: RQU, RQV: RQV};
}
function constrainedV(P) {
  var s, k, it, V = [];
  for (s = 0; s < N; s++) V[s] = 0;
  for (it = 0; it < 20000; it++) {
    var d = 0;
    for (s = 0; s < N; s++) {
      if (!viable[s]) continue;
      var best = -Infinity;
      for (k = 0; k < QV[s].length; k++) { var q = rew(s, P) + P.g * V[SUCC[s][QV[s][k]]]; if (q > best) best = q; }
      var dd = Math.abs(best - V[s]); if (dd > d) d = dd; V[s] = best;
    }
    if (d < 1e-9) break;
  }
  return V;
}
// numerical value iteration for the penalised problem with slip eps (Gauss-Seidel sweeps)
function qval(V, i, kk, p, P) {
  var j, t;
  var acts = AV[i], m = acts.length, q = rew(i, P);
  for (j = 0; j < m; j++) {
    var pr = (j === kk ? 1 - P.e : 0) + P.e / m;
    if (pr <= 0) continue;
    t = SUCC[i][acts[j]];
    q += pr * (t < 0 ? -P.g * p : P.g * V[t]);
  }
  return q;
}
function solve(p, P, V0) {
  var s, k, it, V = [];
  for (s = 0; s < N; s++) V[s] = V0 ? V0[s] : 0;
  for (it = 0; it < 20000; it++) {
    var d = 0;
    for (s = 0; s < N; s++) {
      var best = -Infinity, m = AV[s].length;
      for (k = 0; k < m; k++) { var q = qval(V, s, k, p, P); if (q > best) best = q; }
      var dd = Math.abs(best - V[s]); if (dd > d) d = dd; V[s] = best;
    }
    if (d < 1e-9 * (1 + Math.abs(p))) break;
  }
  return V;

